//! Golden differential tests against the Go implementation (fixtures generated by
//! `go run -mod=vendor ./hack/golden/bfocplookup crates/ctrl-bfocplookup/tests/fixtures`).
//!
//! Each scenario runs [`ImageLookup::lookup_blue_field_ocp_layer_image`] against `ctrlrt-fake`
//! with a fake [`ImageChecker`] (and, for digest release images, an in-process rules registry
//! serving the fixture's responses) and compares, byte for byte: every step's result, error
//! string, events and checked image references, and the `encoding/json` bytes of the caller's
//! in-memory DPFHCPProvisioner and of the stored copy (conditions, status, observedGeneration).
//!
//! Normalization (also applied by the Go generator): the registry address is replaced by
//! "REGISTRY" and condition `lastTransitionTime` (`metav1.Now()`) is set to
//! `2025-01-01T00:00:00Z`.

mod support;

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use apis::provisioning::v1alpha1 as provisioningv1alpha1;
use async_trait::async_trait;
use ctrl_bfocplookup::{ImageChecker, ImageLookup};
use ctrlrt::k8s_openapi::ByteString;
use ctrlrt::k8s_openapi::api::core::v1::Secret;
use ctrlrt::k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, Time};
use ctrlrt::{Ctx, FakeRecorder, ObjectKey, Recorder};
use ctrlrt_fake::{FakeClientBuilder, InitObject, Scheme, obj};
use registry::authn::Keychain;
use registry::name::Reference;
use serde::Deserialize;
use support::{Rule, RulesRegistry};

const TEST_REPOSITORY: &str = "quay.io/test-org/bluefield-os";
const TAGGED_RELEASE: &str = "quay.io/openshift-release-dev/ocp-release:4.19.0-ec.5-x86_64";

#[derive(Debug, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
struct Step {
    requeue: bool,
    requeue_after: i64,
    error: String,
    events: Vec<String>,
    checked: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    rules: Vec<Rule>,
    steps: Vec<Step>,
    objects: BTreeMap<String, String>,
}

fn fixture(name: &str) -> Fixture {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

struct FakeChecker {
    errs: Vec<&'static str>,
    n: Mutex<usize>,
    calls: Mutex<Vec<String>>,
}

#[async_trait]
impl ImageChecker for FakeChecker {
    async fn check_tag(
        &self,
        _ctx: &Ctx,
        r: &Reference,
        _keychain: Arc<dyn Keychain>,
    ) -> ctrlrt::Result<()> {
        self.calls.lock().unwrap().push(r.to_string());
        let mut n = self.n.lock().unwrap();
        let i = (*n).min(self.errs.len().saturating_sub(1));
        *n += 1;
        match self.errs.get(i) {
            None | Some(&"") => Ok(()),
            Some(e) => Err(anyhow::anyhow!(e.to_string())),
        }
    }
}

fn provisioner(release_image: &str) -> provisioningv1alpha1::DPFHCPProvisioner {
    let mut p = provisioningv1alpha1::DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some("test-provisioner".into()),
            namespace: Some("test-ns".into()),
            generation: Some(3),
            uid: Some("uid-1".into()),
            ..Default::default()
        },
        ..Default::default()
    };
    p.spec.ocp_release_image = release_image.into();
    p.spec.pull_secret_ref.name = "pull-secret".into();
    p
}

fn pull_secret(data: &[(&str, &[u8])]) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some("pull-secret".into()),
            namespace: Some("test-ns".into()),
            ..Default::default()
        },
        data: Some(
            data.iter()
                .map(|(k, v)| (k.to_string(), ByteString(v.to_vec())))
                .collect(),
        ),
        type_: Some("kubernetes.io/dockerconfigjson".into()),
        ..Default::default()
    }
}

fn good_secret() -> Option<Secret> {
    Some(pull_secret(&[(
        ".dockerconfigjson",
        br#"{"auths":{"quay.io":{"auth":"dTpw"}}}"#,
    )]))
}

fn normalize(p: &mut provisioningv1alpha1::DPFHCPProvisioner) {
    let fixed: Time = Time("2025-01-01T00:00:00Z".parse().unwrap());
    for c in &mut p.status.conditions {
        c.last_transition_time = fixed.clone();
    }
}

fn encode(p: &provisioningv1alpha1::DPFHCPProvisioner) -> String {
    String::from_utf8(gocompat::json::to_go_json(p).unwrap()).unwrap()
}

enum Release {
    Tagged,
    Empty,
    /// `REGISTRY/ocp/release@<manifest digest from the fixture rules>`
    Digest,
    Literal(&'static str),
}

struct Scenario {
    name: &'static str,
    release: Release,
    repository: &'static str,
    secret: Option<Secret>,
    no_stored: bool,
    checker: Vec<&'static str>,
    steps: usize,
}

impl Default for Scenario {
    fn default() -> Self {
        Self {
            name: "",
            release: Release::Tagged,
            repository: TEST_REPOSITORY,
            secret: good_secret(),
            no_stored: false,
            checker: vec![],
            steps: 1,
        }
    }
}

async fn run(sc: Scenario) {
    let fx = fixture(sc.name);
    let reg = RulesRegistry::start(fx.rules.clone()).await;
    let manifest_digest = fx
        .rules
        .iter()
        .find_map(|r| {
            r.path
                .strip_prefix("/v2/ocp/release/manifests/")
                .map(str::to_string)
        })
        .unwrap_or_default();
    let release = match sc.release {
        Release::Tagged => TAGGED_RELEASE.to_string(),
        Release::Empty => String::new(),
        Release::Digest => format!("{}/ocp/release@{}", reg.host, manifest_digest),
        Release::Literal(s) => s.replace("REGISTRY", &reg.host),
    };

    let mut cr = provisioner(&release);
    let mut objs: Vec<InitObject> = vec![];
    if !sc.no_stored {
        objs.push(obj(&cr));
    }
    if let Some(s) = &sc.secret {
        objs.push(obj(s));
    }
    let c = FakeClientBuilder::new()
        .with_scheme(
            Scheme::new()
                .register::<provisioningv1alpha1::DPFHCPProvisioner>()
                .register::<Secret>(),
        )
        .with_objects(objs)
        .with_status_subresource::<provisioningv1alpha1::DPFHCPProvisioner>()
        .build();
    let rec = Arc::new(FakeRecorder::new(100));
    let checker = Arc::new(FakeChecker {
        errs: sc.checker.clone(),
        n: Mutex::new(0),
        calls: Mutex::new(vec![]),
    });
    let mut lookup = ImageLookup::new(c.clone(), rec.clone() as Recorder);
    lookup.image_checker = checker.clone();
    lookup.set_repository(sc.repository);

    let key = ObjectKey::new("test-ns", "test-provisioner");
    let mut steps = vec![];
    for _ in 0..sc.steps {
        if !sc.no_stored {
            // Like a reconcile: start from the stored object.
            cr = c.get(&key).await.unwrap();
        }
        let res = lookup
            .lookup_blue_field_ocp_layer_image(&Ctx::background(), &mut cr)
            .await;
        let (r, error) = match res {
            Ok(r) => (r, String::new()),
            Err(e) => (ctrlrt::ReconcileResult::default(), reg.norm(&e.to_string())),
        };
        steps.push(Step {
            requeue: r.requeue,
            requeue_after: r.requeue_after.as_nanos() as i64,
            error,
            events: rec.drain().iter().map(|e| reg.norm(e)).collect(),
            checked: std::mem::take(&mut *checker.calls.lock().unwrap())
                .iter()
                .map(|c| reg.norm(c))
                .collect(),
        });
    }
    assert_eq!(steps, fx.steps, "{}: steps", sc.name);

    normalize(&mut cr);
    assert_eq!(
        reg.norm(&encode(&cr)),
        fx.objects["provisioner.memory"],
        "{}: in-memory provisioner",
        sc.name
    );
    let stored = c
        .get::<provisioningv1alpha1::DPFHCPProvisioner>(&key)
        .await
        .ok()
        .map(|mut s| {
            normalize(&mut s);
            reg.norm(&encode(&s))
        })
        .unwrap_or_default();
    assert_eq!(
        stored, fx.objects["provisioner.stored"],
        "{}: stored provisioner",
        sc.name
    );
}

#[tokio::test]
async fn golden_empty_release_image() {
    run(Scenario {
        name: "empty_release_image",
        release: Release::Empty,
        steps: 2,
        ..Default::default()
    })
    .await;
}

